There exists a function $\varepsilon(n) \in o(\log n / n)$ such that the size of a largest temporally connected component in a temporal Erd\H{o}s-R\'enyi{} random graph is
	\begin{enumerate}
		\item[(i)] $o(n)$ \aas, if $p<\frac{\log n}{n} - \varepsilon(n)$; and
		\item[(ii)] $n-o(n)$ \aas, if $p>\frac{\log n}{n} + \varepsilon(n)$.
	\end{enumerate}

Let $u\in V$. For any node $w\in V\setminus \{u\}$, we define
	\[
		V_{u,w}:=\{v\in V\setminus\{u,w\}: \{u,v\}\in E(G) \text{ and } \{v,w\}\in E(G)\}
	\]
	and observe that $|V_{u,w}|\ge 2(\delta(G) -1) - (n-2)\ge (2\beta -1)n$. We now define the following events (1) $R_w$ is the event that $u$ can reach $w$, (2) for $v\in V_{u,w}$, $S_{v,w}$ is the event that $u$ can reach $w$ in exactly two hops via $v$. Then clearly, for each $v\in V_{u,w}$, $\mathbb{P}[S_{v,w}]=p^2/2$.
	We thus get
	\begin{align*}
		\mathbb{P}[\overline{R_w}]
		\le \mathbb{P}\Big[\bigcap_{v\in V_{u,w}} \overline{S_{v,w}}\Big]
		= \prod_{v\in V_{u,w}} \mathbb{P} [ \overline{S_{v,w}} ]
		\le \Big(1 - \frac{p^2}{2}\Big)^{(2\beta -1)n}
		\le \\ e^{- \frac{p^2}{2}(2\beta -1)n}
		= n^{- \frac{\alpha^2(2\beta -1)}{2}}
	\end{align*}
	using the definition of $p$ in the last step.
	It remains to use a union bound over all  $w\in V\setminus \{u\}$ to conclude that $u$ can reach all nodes with probability at least $1 - n^{- \frac{\alpha^2(2\beta -1)}{2} + 1}$.

We thus get
	\begin{align*}
		\mathbb{P}[\overline{R_w}]
		\le \mathbb{P}\Big[\bigcap_{v\in V_{u,w}} \overline{S_{v,w}}\Big]
		= \prod_{v\in V_{u,w}} \mathbb{P} [ \overline{S_{v,w}} ]
		\le \Big(1 - \frac{p^2}{2}\Big)^{(2\beta -1)n}
		\le \\ e^{- \frac{p^2}{2}(2\beta -1)n}
		= n^{- \frac{\alpha^2(2\beta -1)}{2}}
	\end{align*}
	using the definition of $p$ in the last step.

Let $\mathcal{G}=(V, E, \lambda)$ be a temporal graph, let $S\subseteq V$ be a set of vertices and let $\mathcal{G}_F=(V_F, E_F, \lambda_F)$ be an increasing temporal forest for $S$.
	\begin{enumerate}
			\item Then $\mathcal{G}_F$ is a \emph{partial foremost forest for $S$}, if, for all $v\in V_F \setminus S$, the unique temporal $(S, v)$-path in $\mathcal{G}_F$ is a foremost $(S, v)$-path in $\mathcal{G}$.
			\item A partial foremost forest for $S$ is a \emph{foremost forest for $S$} if $V_F$ contains all vertices reachable from $S$ in $\mathcal{G}$, i.e., $V_F=\{v\in V: \exists (u, v)\text{-temporal path in $\mathcal G$ for some }u\in S\}$.
			\item A (partial) foremost forest for $\{v\}$ is a \emph{(partial) foremost tree for $v$}.
		\end{enumerate}

\caption{\textsc{Foremost Forest}}
	\Input{Simple temporal graph $\mathcal{G}=(V, E, \lambda)$; set of nodes $S\subseteq V$.}
	\Output{Foremost forest for $S$.}
	\smallskip
	$k = |S| - 1$,
	$\mathcal{G}^{k}_F=(S, \emptyset, \emptyset)$\;
	\While{$\mathrm{ext}(\mathcal{G}^k_F)\neq \emptyset$}{
		$k := k + 1$\;
		$e_k := arg\,min \{ \lambda(e) \mid e \in \mathrm{ext}(\mathcal{G}^{k-1}_F)\}$\;
		$\mathcal{G}^k_F := \mathcal{G}^{k-1}_F \cup e_k$\;
	}
  \Return{$\mathcal{G}^k_F$}

\Input{Simple temporal graph $\mathcal{G}=(V, E, \lambda)$; set of nodes $S\subseteq V$.}
	\Output{Foremost forest for $S$.}
	\smallskip
	$k = |S| - 1$,
	$\mathcal{G}^{k}_F=(S, \emptyset, \emptyset)$

\While{$\mathrm{ext}(\mathcal{G}^k_F)\neq \emptyset$}{
		$k := k + 1$\;
		$e_k := arg\,min \{ \lambda(e) \mid e \in \mathrm{ext}(\mathcal{G}^{k-1}_F)\}$\;
		$\mathcal{G}^k_F := \mathcal{G}^{k-1}_F \cup e_k$

$\mathcal{G}_F^k$ is a partial foremost forest, i.e., for all $v\in V(\mathcal{G}_F^k) \setminus S$, the unique temporal $(S, v)$-path in $\mathcal{G}_F^k$ is a foremost $(S, v)$-path in $\mathcal{G}$
    \item $\mathcal{G}_F^k$ is a foremost forest, i.e., $V(\mathcal{G}_F^k)=\{v\in V: \exists (u, v)\text{-temporal path in $G$ for some }u\in S\}$.
  \end{enumerate}

We then define random variables
\[
  Y^S_{s-1} := 0 \text{ and }
  Y^S_k := \lambda(e^S_{k})\text{ for $k\in [s, n-s-1]$},
\]
where, extending the notation of \cref{alg: foremost forest} by a superscript denoting the input set $S$, we set $\mathcal{G}_F^{s-1, S} := (S, \emptyset, \emptyset)$
and, for every $k\in [s, n-s-1]$,
\begin{equation*}
  \begin{split}
    E^S_k   &:= V(\mathcal{G}_F^{k-1, S}) \times \big( V \setminus V(\mathcal{G}_F^{k-1, S}) \big)\\
    e^S_{k} &:= \arg\min \{ \lambda(e) ~|~ e \in E^S_k \text{ and } \mathcal{G}_F^{k-1, S} \cup \{e \} \text{ is an increasing temporal forest for }S \}, \\
    \mathcal{G}_F^{k, S}   &:= \mathcal{G}_F^{k-1, S} \cup \{ e^S_{k} \}.
  \end{split}
\end{equation*}

We get
  \begin{equation*}
    \begin{split}
      \sum_{i=s}^{n-s-1} c_i^2
      & = \sum_{i=s}^{n-s-1}\frac{\big(2 \log{(\min\{i, n- i\})} + \log \log{n}\big)^2}{(i\cdot (n- i))^2s^{-2/3}}
      \\ &\leq \sum_{i=s}^{n-s-1}\frac{\big(2 \log{(\min\{i, n- i\})} \cdot \log \log{n}\big)^2}{(i\cdot (n- i))^2s^{-2/3}}
      \\ &\leq \frac{4 (\log\log{n})^2}{s^{-2/3}} \Bigg( \sum_{i=s}^{\lfloor n/2 \rfloor}
      \frac{(\log i )^2}{ i^2\cdot (n/2)^2}
      + \sum_{i=\lfloor n/2 \rfloor+1}^{n-s-1} \frac{(\log(n- i))^2}{(n/2)^2(n- i)^2} \Bigg)
      \\ &\leq \frac{32 (\log \log{n})^2}{n^2s^{-2/3}} \sum_{i=s}^{\infty}\frac{(\log{i})^2}{i^2}
      \\ &\leq \frac{32 (\log \log{n})^2}{n^2s^{-2/3}} \int_{s-1}^{\infty}\frac{(\log{x})^2}{x^2}dx
      \\ &= \frac{32 (\log \log{n})^2}{n^2s^{-2/3}}\frac{(\log(s-1))^2 + 2 \log(s-1) + 2}{s - 1}
      \\ &\leq \frac{64 (\log \log{n})^2 (\log s)^2}{n^2s^{1/3}},
    \end{split}
  \end{equation*}
  assuming that $n$ and thus $s$ is sufficiently large.

We observe that
  \begin{equation} \begin{split}
    \mathbb{P} \big[ \capped{X}^S_k \neq X^S_k \big]
    &= \mathbb{P} \big[X^S_k > c_k \big]
    \leq (1 - c_k)^{\abs{E_k^S}}
    \leq (1 - c_k)^{k (n-k) \cdot(1-\delta_k)}
    \leq e^{-k (n-k) \cdot(1-\delta_k) \cdot c_{k}}
    \\&= \big(e^{-\log((\min\{ k, n-k\})^2 \log{n})}\big)^{s^{1/3}\cdot(1-\delta_k)}
    \le \big((\min\{ k, n-k\})^2 \log{n}\big)^{-s^{1/3}/2},
  \end{split}
  \end{equation}
  where we used that $\delta_k=(\log n)^a/(n-k)\le (\log n)^a/(s+1)\le (\log n)^{a-b}\le 1/2$, since $k\le n - s - 1$ and $b\ge a + 1$.
  Therefore
  \begin{align*}
      \sum_{k=s}^{n-s-1}
      \mathbb{P} \big[\capped{X}^S_k \neq X^S_k \big] & \leq
      \sum_{k=s}^{n-s-1} \big((\min\{ k, n-k\})^2 \log{n}\big)^{-s^{1/3}/2}
      \\ &= \frac{1}{(\log{n})^{s^{1/3}/2}} \left( \sum_{k=s}^{\lfloor n/2 \rfloor} \frac{1}{k^{s^{1/3}}} +
      \sum_{k=\lfloor n/2 \rfloor+1}^{n-s-1} \frac{1}{(n- k)^{s^{1/3}}} \right)
      \\ &\leq \frac{2}{(\log{n})^{s^{1/3}/2}} \sum_{k=s}^{\infty}\frac{1}{k^{s^{1/3}}}
      \\ &\leq \frac{2}{(\log{n})^{s^{1/3}/2}} \int_{s-1}^{\infty}\frac{1}{x^{s^{1/3}}}dx
      \\ &= \frac{2}{(\log{n})^{s^{1/3}/2}} \frac{1}{(s^{1/3} - 1)\cdot (s-1)^{s^{1/3}-1}}
      \\ &\le \frac{2}{(\log{n})^{s^{1/3}/2}} \frac{1}{(s^{1/3} - 1)^{s^{1/3}}}
      \\ &\le \frac{1}{(\log{n})^{s^{1/3}/2} \cdot s^{s^{1/3}/4}},
  \end{align*}
  using that $n$ and thus $s$ is sufficiently large. It remains to use that $s\ge (\log n)^b$ and $b\ge a + 1 \ge 2$ to obtain the bound of $1/(\log n)^{s^{1/3}}$.

\begin{split}
    \mathbb{P} \big[ \capped{X}^S_k \neq X^S_k \big]
    &= \mathbb{P} \big[X^S_k > c_k \big]
    \leq (1 - c_k)^{\abs{E_k^S}}
    \leq (1 - c_k)^{k (n-k) \cdot(1-\delta_k)}
    \leq e^{-k (n-k) \cdot(1-\delta_k) \cdot c_{k}}
    \\&= \big(e^{-\log((\min\{ k, n-k\})^2 \log{n})}\big)^{s^{1/3}\cdot(1-\delta_k)}
    \le \big((\min\{ k, n-k\})^2 \log{n}\big)^{-s^{1/3}/2},
  \end{split}

We observe that
  \begin{equation} \begin{split}
    \mathbb{P} \big[ \capped{X}^S_k \neq X^S_k \big]
    &= \mathbb{P} \big[X^S_k > c_k \big]
    \leq (1 - c_k)^{\abs{E_k^S}}
    \leq (1 - c_k)^{k (n-k) \cdot(1-\delta_k)}
    \leq e^{-k (n-k) \cdot(1-\delta_k) \cdot c_{k}}
    \\&= \big(e^{-\log((\min\{ k, n-k\})^2 \log{n})}\big)^{s^{1/3}\cdot(1-\delta_k)}
    \le \big((\min\{ k, n-k\})^2 \log{n}\big)^{-s^{1/3}/2},
  \end{split}
  \end{equation}
  where we used that $\delta_k=(\log n)^a/(n-k)\le (\log n)^a/(s+1)\le (\log n)^{a-b}\le 1/2$, since $k\le n - s - 1$ and $b\ge a + 1$.

Therefore
  \begin{align*}
      \sum_{k=s}^{n-s-1}
      \mathbb{P} \big[\capped{X}^S_k \neq X^S_k \big] & \leq
      \sum_{k=s}^{n-s-1} \big((\min\{ k, n-k\})^2 \log{n}\big)^{-s^{1/3}/2}
      \\ &= \frac{1}{(\log{n})^{s^{1/3}/2}} \left( \sum_{k=s}^{\lfloor n/2 \rfloor} \frac{1}{k^{s^{1/3}}} +
      \sum_{k=\lfloor n/2 \rfloor+1}^{n-s-1} \frac{1}{(n- k)^{s^{1/3}}} \right)
      \\ &\leq \frac{2}{(\log{n})^{s^{1/3}/2}} \sum_{k=s}^{\infty}\frac{1}{k^{s^{1/3}}}
      \\ &\leq \frac{2}{(\log{n})^{s^{1/3}/2}} \int_{s-1}^{\infty}\frac{1}{x^{s^{1/3}}}dx
      \\ &= \frac{2}{(\log{n})^{s^{1/3}/2}} \frac{1}{(s^{1/3} - 1)\cdot (s-1)^{s^{1/3}-1}}
      \\ &\le \frac{2}{(\log{n})^{s^{1/3}/2}} \frac{1}{(s^{1/3} - 1)^{s^{1/3}}}
      \\ &\le \frac{1}{(\log{n})^{s^{1/3}/2} \cdot s^{s^{1/3}/4}},
  \end{align*}
  using that $n$ and thus $s$ is sufficiently large.

For a set of vertices $S$ and every $k\in[s, n - s - 1]$ we have
  \begin{flalign*}
     \text{(i)}&& \frac{1-Y_{k-1}^{S}}{k(n-k) + 1}  &\leq  \mathbb{E}[X_k^{S} \mid \mathcal A_{k-1}^{S}]  \leq  \frac{1}{k(n-k)(1-\delta_k) + 1};&
     \\ \text{(ii)}&&  \left( 1 - \frac{1}{(\log n)^{s^{1/3}}} \right) \cdot \frac{1-Y_{k-1}^{S}}{k(n-k) + 1}
     &\leq \mathbb{E}[\capped{X}_k^{S} \mid \mathcal A_{k-1}^{S}]
     \leq \frac{1}{k(n-k)(1-\delta_k) + 1}.
  \end{flalign*}

\begin{split}
      \frac{1-Y_{k-1}^{S}}{k(n-k) + 1}
      \leq
      \frac{1-Y_{k-1}^{S}}{k(n-k)(1-r_k) + 1}
      &=
      \mathbb{E}[ X_k' \mid Y_{k-1}^S]
      \\&\leq
      \mathbb{E}[ X_k^{S} \mid \mathcal A^v_{k-1}]
      \\&\leq
      \mathbb{E}[ X_k'']
      =
      \frac{1}{k(n-k)(1-r_k) + 1}
      \\&
      \leq
      \frac{1}{k(n-k)(1-\delta_k) + 1}.
    \end{split}

Notice that for any two edges $e,f \in E_k^{S}$ such that $\lambda(f) < Y_{k-1}^{S} \leq \lambda(e)$
  we have $w_k^{S}(e) < w_k^{S}(f)$. This together with the fact that the edge labels of $e_s^S,\ldots, e_{s+k+1}^S$ are increasing (see~\cref{lem:foremostTree}~(ii)) implies that $e_k^{S}$ is exactly
  the edge on which the minimum of $w_k^{S}$ is attained, that is,
  \begin{equation} e_k^{S}
    = \arg\min \{w_k^{S}(e) \mid e \in E_k^{S} \},
  \end{equation}

For a set of nodes $S$ of cardinality $s\ge (\log n)^b$ with $b\ge 3$, with probability at least $1-n^{-\log n /4}$, for every $k\in [s, n-s-1]$, it holds that
  \begin{flalign*}
    \text{(i)} &&   \left( 1 - \frac{\log{n}}{\sqrt{n}} \right) \cdot \frac{1}{k(n-k) + 1}  &\leq  \mathbb{E}[X_k^{S} \mid \mathcal A_{k-1}^{S}]  \leq  \frac{1}{k(n-k)(1-\delta_k) + 1};&
    \\ \text{(ii)}  && \left( 1 - \frac{2\log n}{\sqrt{n}} \right) \cdot \frac{1}{k(n-k) + 1}  &\leq  \mathbb{E}[\capped{X}_k^{S} \mid \mathcal A_{k-1}^{S}]  \leq  \frac{1}{k(n-k)(1-\delta_k) + 1}.
  \end{flalign*}

For $k \in[s, n - 1]$, it holds that
  \begin{align*}
    &\frac{\log k - \log  s + \log (n -  s + 1) - \log(n - k)}{n} - \frac{3}{n}
    \\&\qquad \leq \sum_{i= s}^k \frac{1}{i(n-i) + 1} \leq \sum_{i= s}^k \frac{1}{i(n-i)}
    \\&\qquad \qquad\leq \frac{\log k - \log  s + \log (n -  s + 1) - \log(n - k)}{n} + \frac{3}{n}.
  \end{align*}

We have that
  \begin{align*}
    \sum_{i= s}^k \frac{1}{i(n-i) + 1}
    &\leq \sum_{i=1}^k \frac{1}{i(n-i)}
    \\ &= \frac{1}{n} \sum_{i= s}^k \left( \frac{1}{i} + \frac{1}{n-i} \right)
    \\ &= \frac{1}{n} \left(\sum_{i=1}^{k} \frac{1}{i} - \sum_{i=1}^{ s - 1} \frac{1}{i} + \sum_{i=1}^{n -  s} \frac{1}{i} - \sum_{i=1}^{n-k-1} \frac{1}{i}\right)
    \\ &\leq \frac{\log k + 1 - \log  s + \log (n- s) + 1 - \log(n - k)}{n}
    \\ &\leq \frac{\log k - \log  s + \log (n -  s + 1) - \log(n - k)}{n} + \frac{3}{n}
    \intertext{as well as}
    \sum_{i= s}^k \frac{1}{i(n-i) + 1}
    &\geq  \sum_{i= s}^k \frac{1}{i(n+1-i)}
    \\&= \frac{1}{n+1}  \sum_{i= s}^k \left( \frac{1}{i} + \frac{1}{n+1-i} \right)
    \\ &= \frac{1}{n+1} \left( \sum_{i=1}^{k} \frac{1}{i} - \sum_{i=1}^{ s - 1} \frac{1}{i} + \sum_{i=1}^{n + 1 -  s} \frac{1}{i} - \sum_{i=1}^{n - k} \frac{1}{i} \right)
    \\ &\geq \frac{\log k - (\log  s + 1) + \log (n- s+1) - (\log(n-k) + 1)}{n+1}
    \\ &= \frac{\log k - \log  s + \log (n -  s + 1) - \log(n-k)}{n} \cdot\left(1 - \frac{1}{n+1}\right) - \frac{2}{n + 1}
    \\ &\geq \frac{\log k - \log  s + \log (n -  s + 1) - \log(n - k)}{n} - \frac{3}{n}.\qedhere
  \end{align*}

We will first prove that, with probability at least $1 - 2n^{-\log n/4}$, for a fixed set $S$ of $s$ vertices, for all $k\in [ s, n- s-1]$,
  \begin{align} \left| \capped{Y}_k^{S} - \sum_{i=s}^k \frac{1}{i(n-i) + 1} \right| < \frac{2\log\log n}{n}.
  \end{align}
  From there it will be straightforward to reach the statement of the proposition.

  We note that, for $i\in [s, k]$, we have that $\delta_i = \frac{(\log n)^a}{n - i} \le \frac{(\log n)^a}{s} \le \frac{1}{\log n}$ using that $b\ge a + 1$. Hence,
  $1/(1-\delta_i) \le  1 + 2/\log n$ and thus
  \[
    \frac{1}{i(n-i)(1-\delta_i) + 1}
    \le \Big(1 + \frac{2}{\log n}\Big) \cdot \frac{1}{i(n-i)+ 1}.
  \]
  By \cref{cor:ExpOfcappedXk}~(ii), with probability at least $1-n^{-\log n/4}$,
  for every set of vertices $S$ with $ s\ge (\log n)^{b}$, where $b\ge 3$ and every $k\in[s, n -  s - 1]$ we thus have
  \begin{equation} \left|\sum_{i= s}^k \mathbb{E}[\capped{X}^S_i \mid \mathcal A^S_{i-1}] - \sum_{i= s}^k \frac{1}{i(n-i) + 1} \right|
    \le \max
      \left\{
        \frac{2\log n}{\sqrt{n}}, \frac{2}{\log n}
      \right\}
    \cdot \sum_{i= s}^k \frac{1}{i(n-i) + 1}
  \end{equation}
  If $s\ge (\log n)^b$ with $b\ge 13$, we have by \cref{lm:YCapConcentrate} that with probability at least $1 - n^{-\log n}$,
  for every $k\in [ s, n- s-1]$,
  \begin{equation} \left|\capped{Y}^S_k - \sum_{i= s}^k \mathbb{E}[\capped{X}^S_i \mid \mathcal A^S_{i-1}] \right|
      \leq \frac{\log\log n}{n}.
  \end{equation}
  Hence, \eqref{eq:diffYhatExpHarmonic} and \eqref{eq:Yhat} together yield that, with probability at least $1 - 2n^{-\log n/4}$, for every $k\in [ s, n- s-1]$,
  \begin{align*}
          \left| \capped{Y}_k^{S} -  \sum_{i=s}^k \frac{1}{i(n-i) + 1} \right| 
          \hskip-2cm&
          \\&\le \left|\capped{Y}^S_k - \sum_{i= s}^k \mathbb{E}[\capped{X}^S_i \mid \mathcal A^S_{i-1}] \right|
      + \left|\sum_{i= s}^k \mathbb{E}[\capped{X}^S_i \mid \mathcal A^S_{i-1}] - \sum_{i= s}^k \frac{1}{i(n-i) + 1} \right|
    \\&\le
    \frac{\log\log n}{n} + \frac{2}{\log n} \cdot \sum_{i= s}^k \frac{1}{i(n-i) + 1}.
  \end{align*}
  Applying \cref{cl: favsum} and assuming that $n$ is sufficiently large enough, we get
  \begin{align*}
    \frac{2}{\log n} \cdot \sum_{i= s}^k \frac{1}{i(n-i) + 1}
    \leq
    \frac{2}{\log n} \cdot
    \left(
      \frac{2 \log n}{n} + \frac{3}{n}
    \right)
     \leq\frac{\log\log n}{n}
  \end{align*}
  and this completes the proof of~\eqref{eq: trunc}.

  Now by~\cref{lm:capped_eq_uncapped} and the assumption on $b$, and thus on $s$, it holds that the truncated and non-truncated random variables coincide with probability at least $1-n^{-\log \log n}$. Using that $2n^{-\log n/4}\le n^{-\log\log n}$ concludes the proof.

