If $s\ge (\log n)^b$ with $b\ge 13$, we have by \cref{lm:YCapConcentrate} that with probability at least $1 - n^{-\log n}$,
  for every $k\in [ s, n- s-1]$,
  \begin{equation} \left|\capped{Y}^S_k - \sum_{i= s}^k \mathbb{E}[\capped{X}^S_i \mid \mathcal A^S_{i-1}] \right|
      \leq \frac{\log\log n}{n}.
  \end{equation}

Applying \cref{cl: favsum} and assuming that $n$ is sufficiently large enough, we get
  \begin{align*}
    \frac{2}{\log n} \cdot \sum_{i= s}^k \frac{1}{i(n-i) + 1}
    \leq
    \frac{2}{\log n} \cdot
    \left(
      \frac{2 \log n}{n} + \frac{3}{n}
    \right)
     \leq\frac{\log\log n}{n}
  \end{align*}
  and this completes the proof of~\eqref{eq: trunc}.

Clearly it suffices to consider the case $d > s$.
  To prove the lemma, it suffices to show that, with probability at least $1 - 2n^{-\log\log n}$, we have
  \[
      \left| Y^S_{d-1} - \frac{z\log n - \log s}{n} \right|
      <
      \frac{3\log \log n}{n}.
  \]
  Let
  \begin{align*}
    L \coloneqq{}& \log (d -1) - \log s + \log (n -  s + 1) - \log(n - d + 1).
  \end{align*}
  Then, for sufficiently large $n$,
  \begin{align*}
    L\le{}& \log (n -  s + 1) - \log s + \log\left( n^z \right) - \log\left(n-n^z\right)
    \\ \le{}& \log n - \log s + \log\left( n^z \right) - \log\left(n-n^z\right)
    \\ ={}& z \log n  - \log s - \log\left(1-n^{z-1}\right)
    \\ \leq{}& z \log n  - \log s + \log\left(1+\frac{n^{-\varepsilon}}{1 - n^{-\varepsilon}}\right)
    \\ \le{}& z \log n  - \log s + \frac{n^{-\varepsilon}}{1 - n^{-\varepsilon}}
    \\ \le{}& z \log n - \log  s + 1.
  \end{align*}
  Similarly, for sufficiently large $n$, and using that $s\le n/2$,
  \begin{align*}
    L\ge{}& \log\left(n^z - 1\right) - \log s + \log \left(\frac{n}{2}\right) - \log n
    \\ ={}& z \log n  - \log  s + \log\left(1-n^{-z}\right) - \log 2
    \\ \ge {}& z \log n  - \log  s + \log\left(1-n^{-\varepsilon}\right)- \log 2
    \\ \ge {}& z \log n  - \log  s - 2\log 2
    \\ \ge{}& z \log n - \log  s - 2,
  \end{align*}
  where in the third step we used $z\ge \varepsilon$.
  Then we conclude by \cref{th:YConcEasy} that with probability at least $1 - 2n^{-\log\log n}$
