    \abs*{ Y^S_{d-1} - \frac{{z\log n - \log s}}{n}}
    &\leq
    \abs*{ Y^S_{d-1}- \frac{L}{n} }
    +
    \abs*{ \frac{L}{n} - \frac{z\log n - \log s}{n} }
    \\ &\leq
    \frac{2\log\log n + 3}{n} + \frac{2}{n}
    \le
    \frac{3\log \log n}{n}
  \end{align*}
  holds.

